-- Simple rule base for seasonal suggestions: in these months, this crop needs this machine or skill.
-- Months can wrap around the year end (month_from 11, month_to 1 means Nov, Dec, Jan).
-- Based on the Karnataka crop calendar (kharif June to October, rabi October to March).
CREATE TABLE crop_rules (
    id                 BIGINT       NOT NULL AUTO_INCREMENT,
    crop               VARCHAR(30)  NOT NULL,
    season             VARCHAR(20)  NOT NULL,
    activity           VARCHAR(20)  NOT NULL,
    month_from         INT          NOT NULL,
    month_to           INT          NOT NULL,
    equipment_category VARCHAR(30)  NULL,
    skill              VARCHAR(30)  NULL,
    tip                VARCHAR(255) NOT NULL,
    PRIMARY KEY (id),
    KEY idx_crop_rules_crop (crop)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

